insert into materi (id, mapel, tingkat, rombel, judul, teks, rangkuman) overriding system value values (1, 'IPA', 'VIII', array['A', 'B', 'C', 'D', 'E', 'F'], 'Sistem Pernapasan Manusia', array['Sistem pernapasan adalah proses pertukaran oksigen dan karbon dioksida di dalam tubuh manusia.', 'Hidung adalah organ pernapasan yang menyaring, menghangatkan, dan melembapkan udara yang masuk.', 'Faring adalah persimpangan antara saluran napas dan saluran makanan.', 'Trakea adalah saluran udara yang menghubungkan laring dengan bronkus.', 'Alveolus adalah tempat pertukaran gas oksigen dan karbon dioksida terjadi.', 'Diafragma adalah otot yang membantu paru-paru mengembang dan mengempis saat bernapas.'], array['Sistem pernapasan memasukkan oksigen dan mengeluarkan karbon dioksida.', 'Urutan organ: hidung, faring, laring, trakea, bronkus, paru-paru.', 'Pertukaran gas terjadi di alveolus dan dibantu otot diafragma.']);
insert into materi (id, mapel, tingkat, rombel, judul, teks, rangkuman) overriding system value values (2, 'Matematika', 'VIII', array['A', 'B', 'C', 'D', 'E', 'F'], 'Persamaan Linear Satu Variabel', array['Persamaan linear satu variabel adalah persamaan yang hanya memiliki satu variabel berpangkat satu.', 'Variabel adalah huruf yang mewakili nilai yang belum diketahui, misalnya x.', 'Koefisien adalah angka yang mengalikan variabel pada sebuah suku.', 'Konstanta adalah suku yang tidak mengandung variabel.', 'Penyelesaian persamaan dilakukan dengan memindahkan suku dan menyetarakan kedua ruas.'], array['Bentuk umum: ax + b = 0 dengan a tidak sama dengan nol.', 'Variabel = yang dicari, koefisien = pengali variabel, konstanta = angka tetap.', 'Langkah penyelesaian: kumpulkan variabel di satu ruas, angka di ruas lain.']);
insert into materi (id, mapel, tingkat, rombel, judul, teks, rangkuman) overriding system value values (3, 'Bahasa Indonesia', 'VIII', array['A', 'B', 'C', 'D', 'E', 'F'], 'Teks Eksplanasi', array['Teks eksplanasi adalah teks yang menjelaskan proses terjadinya suatu fenomena.', 'Struktur teks eksplanasi terdiri dari pernyataan umum, deretan penjelas, dan interpretasi.', 'Pernyataan umum adalah bagian pembuka yang memaparkan fenomena yang akan dibahas.', 'Konjungsi kausalitas adalah kata penghubung sebab akibat, misalnya karena dan sehingga.', 'Interpretasi adalah bagian penutup yang berisi pandangan penulis terhadap fenomena.'], array['Teks eksplanasi menjelaskan sebab-akibat sebuah fenomena, bukan menceritakan.', 'Struktur: pernyataan umum, deretan penjelas, interpretasi.', 'Bahasa berciri konjungsi kausalitas dan istilah teknis.']);
insert into materi (id, mapel, tingkat, rombel, judul, teks, rangkuman) overriding system value values (4, 'Matematika', 'VII', array['A', 'B', 'C', 'D', 'E', 'F'], 'Bilangan Bulat', array['Bilangan bulat adalah bilangan yang terdiri dari bilangan positif, nol, dan bilangan negatif.', 'Bilangan prima adalah bilangan yang hanya memiliki dua faktor, yaitu satu dan bilangan itu sendiri.', 'Nilai mutlak adalah jarak suatu bilangan dari nol pada garis bilangan.', 'Faktor persekutuan terbesar adalah faktor terbesar yang dimiliki dua bilangan atau lebih.'], array['Bilangan bulat mencakup bilangan positif, nol, dan negatif.', 'Bilangan prima hanya punya dua faktor: 1 dan dirinya sendiri.', 'Nilai mutlak selalu positif karena berupa jarak dari nol.']);
insert into materi (id, mapel, tingkat, rombel, judul, teks, rangkuman) overriding system value values (5, 'IPA', 'IX', array['A', 'B', 'C', 'D', 'E', 'F'], 'Sistem Reproduksi pada Manusia', array['Spermatogenesis adalah proses pembentukan sel sperma yang terjadi di dalam testis.', 'Oogenesis adalah proses pembentukan sel telur yang terjadi di dalam ovarium.', 'Fertilisasi adalah proses peleburan sel sperma dengan sel telur.', 'Plasenta adalah organ yang menghubungkan janin dengan dinding rahim ibu.'], array['Spermatogenesis terjadi di testis, oogenesis terjadi di ovarium.', 'Fertilisasi adalah peleburan sperma dan sel telur.', 'Plasenta menyalurkan makanan dan oksigen ke janin.']);
